const SHEETS = [
'Animal','Bench','Planter','Fountain','Lamppost','Bathtub','Sink','Vanity','Fireplace','Table','Statue','MarbleSlab','2026Instock','DoorSurround','MarbleRangeHood','Moulding','StoneMosaicTile','MarbleMedallion', 'Wall-Coverings', 'Exterior-Wall-Decoration', 'Columns', 'Marble+ Basin', 'Marble+ ConsoleTable', 'Carving','WindowSurround', 'Wainscoting', 'BookMatchedSlabs', 'OutdoorCornice', 'Stairs', 'Balustrade'
];
// Clear any leftover data from a previous run
const sd = $getWorkflowStaticData('global');
sd.allProducts = [];

// Rotate which single sheet gets the expensive dead-image-URL health-check
// today -- scanning every image across every row in all 30 sheets every
// single day doesn't scale (confirmed: at only 12/30 categories, the health
// check alone generated 25,000+ HTTP-check items in one run and crashed the
// execution). A persistent cursor advances by one sheet per run, so the full
// catalog gets audited roughly once a month at the current daily schedule
// instead of every single day. New-product image uploads (the cheap, time-
// sensitive part) are unaffected and still run for every sheet every day.
if (typeof sd.healthCheckCursor !== 'number') sd.healthCheckCursor = 0;
const healthCheckSheet = SHEETS[sd.healthCheckCursor % SHEETS.length];
sd.healthCheckCursor = (sd.healthCheckCursor + 1) % SHEETS.length;

return SHEETS.map(s => ({ json: { sheet_name: s, run_health_check: s === healthCheckSheet } }));

// Filter rows that need images and store them in workflow static data.
// Returns a marker item so the Iterate Sheets loop continues.
const sheetName = $('🔁 Iterate Sheets').item.json.sheet_name;
const hasValue  = v => v !== undefined && v !== null && String(v).trim() !== '';

// Only the columns actually used downstream (Phase 2 lookups + Build Sheet
// Update) are carried through -- not the whole row. Spreading the FULL row
// (title/description/SEO/Etsy/pricing/QC columns -- 40+ fields nothing here
// reads) into this array across all 30 sheets bloated the accumulated
// static-data payload enough to crash the run: a single-sheet test stayed
// small enough to succeed, but the full run reliably crashed before
// "📊 Get Collected Products" could ever read it back. Same minimal-row shape
// already used by "🩺 Build URL Checks" for the same reason.
const products = items
  .map(({ json }) => json)
  .filter(r => hasValue(r['Product No.']) && !hasValue(r['IMAGE URL1']))
  .map(r => {
    const row = {
      'Product No.': r['Product No.'],
      row_number: r.row_number,
      sheet_name: sheetName,
      'Shopify_Product_URL': r['Shopify_Product_URL'],
      'Shopify_Update_product_URL': r['Shopify_Update_product_URL'],
      'Fields_to_update': r['Fields_to_update'],
    };
    for (let n = 1; n <= 10; n++) row[`IMAGE URL${n}`] = r[`IMAGE URL${n}`];
    return row;
  });

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.allProducts)) sd.allProducts = [];
sd.allProducts.push(...products);

return [{ json: { _sheetDone: true, sheet: sheetName, added: products.length } }];

// Phase 1 complete. Read the accumulated product list and reset for next run.
const sd = $getWorkflowStaticData('global');
const products = Array.isArray(sd.allProducts) ? [...sd.allProducts] : [];
sd.allProducts = [];
return [{ json: { products, total: products.length } }];

const sheetName = ($('🔁 Iterate Products').item.json.sheet_name || '').toString().trim().toLowerCase();
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === sheetName);
return [exact || { json: { id: '', name: '' } }];

const productNo = ($('🔁 Iterate Products').item.json['Product No.'] || '').toString().trim().toLowerCase();
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === productNo);
return [exact || { json: { id: '', name: '' } }];

const items = $input.all();
const logoFolder = items.find(
  item => /logo/i.test(item.json.name || '')
);
if (!logoFolder) {
  throw new Error(`No LOGO subfolder found for product: ${$('🔁 Iterate Products').item.json['Product No.']}`);
}
return [{ json: { id: logoFolder.json.id, name: logoFolder.json.name } }];

const productNo = $('🔁 Iterate Products').item.json['Product No.'];
const rowNumber  = $('🔁 Iterate Products').item.json.row_number;
const sheetName  = $('🔁 Iterate Products').item.json.sheet_name;

// Dedicated Drive node outputs one item per file — collect them all
const files = $input.all().map(item => ({
  id:       item.json.id,
  name:     item.json.name     || '',
  mimeType: item.json.mimeType || '',
  // Drive reports pixel dimensions for images (requires the "*" fields option
  // on the listing node); undefined when Drive could not extract them.
  width:    item.json.imageMediaMetadata?.width,
  height:   item.json.imageMediaMetadata?.height
}));

const mime = name => {
  const ext = (String(name).split('.').pop() || '').toLowerCase();
  return ext === 'png'  ? 'image/png'
       : (ext === 'jpg' || ext === 'jpeg') ? 'image/jpeg'
       : ext === 'webp' ? 'image/webp'
       : 'image/jpeg';
};

const imageFiles = files.filter(f => /\.(png|jpe?g|webp)$/i.test(f.name));

let primary = null, secondary = null, others = [];
for (const f of imageFiles) {
  const stem = f.name.replace(/\.[^.]+$/, '');
  if (/-p$/i.test(stem))      primary = f;
  else if (/-s$/i.test(stem)) secondary = f;
  else                        others.push(f);
}

// Deterministic order so re-running against the same Drive contents always
// assigns the same slot numbers -- Drive's API listing order is not guaranteed
// stable, which previously made "other" slot assignment look arbitrary.
others.sort((a, b) => a.name.localeCompare(b.name));

const ordered = [];
const entry = (f, slot, role) => ({ id: f.id, fileName: f.name, mimeType: mime(f.name), width: f.width, height: f.height, slot, role });
if (primary)   ordered.push(entry(primary, 'IMAGE URL1', 'primary'));
if (secondary) ordered.push(entry(secondary, 'IMAGE URL2', 'secondary'));
others.forEach((f, i) => ordered.push(entry(f, `IMAGE URL${i + 3}`, 'other')));

return [{ json: { images: ordered, hasImages: ordered.length > 0, row_number: rowNumber, sheet_name: sheetName, product_no: productNo } }];

const { images, row_number, sheet_name, product_no } = $json;
const iterJson = $('🔁 Iterate Products').item.json;
const isRepair = iterJson._reason === 'dead_image_url';

// Shopify rejects images over 25 megapixels or 5000 px on a side ("Media
// processing failed" / "Exceeds 25 megapixels"). Anything over this is
// downscaled before upload; unknown dimensions are treated as oversized so
// they still go through the (aspect-preserving, shrink-only) resize.
const MAX_SIDE = 4800;
const MAX_AREA = 24_000_000;

const staleFileName = (url) => {
  if (!url) return '';
  try { return decodeURIComponent(url.split('?')[0].split('/').pop() || ''); }
  catch (e) { return ''; }
};

return images.map(img => {
  const w = Number(img.width), h = Number(img.height);
  const known = Number.isFinite(w) && Number.isFinite(h) && w > 0 && h > 0;
  const oversized = !known || w > MAX_SIDE || h > MAX_SIDE || (w * h) > MAX_AREA;
  // Whatever this slot currently holds in the sheet (dead, alive, or empty for a
  // brand-new product) is what we try to update in place -- this is what lets a
  // full reclassification avoid creating duplicates for images already fine.
  const staleUrl = String(iterJson[img.slot] || '').trim();
  return { json: {
    photoId:    img.id,
    fileName:   img.fileName,
    mimeType:   img.mimeType,
    slot:       img.slot,
    role:       img.role,
    width:      known ? w : null,
    height:     known ? h : null,
    oversized,
    isRepair,
    staleUrl,
    staleFileName: staleFileName(staleUrl),
    row_number,
    sheet_name,
    product_no
  } };
});

const allItems   = $input.all();
const splitItems = $('🔀 Split Per Image').all();
const bySlot = new Map(splitItems.map(item => [item.json.slot, item.json]));

const uploadedFiles = [];
const failures = [];
for (const item of allItems) {
  const res = item.json;
  const fc  = res?.data?.fileCreate || res?.data?.fileUpdate;
  const returnedAlt = fc?.files?.[0]?.alt;
  const meta = bySlot.get(returnedAlt) || {};
  const slot = meta.slot || returnedAlt;

  // A fileCreate/fileUpdate that "succeeds" as an HTTP call can still reject the
  // file -- previously these were skipped silently, leaving the slot empty and the
  // failure invisible.
  if (res?.errors?.length) {
    failures.push(`${slot || '?'} (${meta.fileName || '?'}): ${JSON.stringify(res.errors)}`);
    continue;
  }
  if (fc?.userErrors?.length) {
    failures.push(`${slot || '?'} (${meta.fileName || '?'}): ${JSON.stringify(fc.userErrors)}`);
    continue;
  }
  if (!fc?.files?.[0]?.id) {
    failures.push(`${slot || '?'} (${meta.fileName || '?'}): no file id returned ${JSON.stringify(res)}`);
    continue;
  }
  if (slot) uploadedFiles.push({ id: fc.files[0].id, slot, fileName: meta.fileName });
}
const first = splitItems[0]?.json || {};
if (failures.length) {
  throw new Error(`Shopify file ${first.isRepair ? 'update' : 'create'} failed for ${first.product_no} (${first.sheet_name} row ${first.row_number}): ${failures.join(' | ')}`);
}
return [{ json: { uploadedFiles, row_number: first.row_number, sheet_name: first.sheet_name, product_no: first.product_no, attempts: 0 } }];

const { nodes = [], uploadedFiles, row_number, sheet_name } = $json;
const iterJson = $('🔁 Iterate Products').item.json;
const isRepair = iterJson._reason === 'dead_image_url';

const idToUrl = {};
for (const node of nodes) {
  // GenericFile exposes url directly; MediaImage exposes image.url
  const url = node?.url || node?.image?.url;
  if (url) idToUrl[node.id] = url;
}

const update = { row_number, sheet_name };
const updatedSlots = [];
const freshSlots = new Set();
for (const { id, slot } of uploadedFiles) {
  const url = idToUrl[id];
  if (url) {
    update[slot] = url;
    updatedSlots.push(slot);
    freshSlots.add(slot);
    if (slot === 'IMAGE URL1') update['Picture'] = '=IMAGE("' + url + '",1)';
  }
}

// A repair fully reclassifies the row from Drive -- any slot that was previously
// populated but Drive no longer has material for (a leftover duplicate slot from
// the old full-row-reupload bug) is cleared instead of left pointing at a dead URL.
if (isRepair) {
  for (let n = 1; n <= 10; n++) {
    const slot = `IMAGE URL${n}`;
    const hadValue = String(iterJson[slot] || '').trim() !== '';
    if (hadValue && !freshSlots.has(slot)) {
      update[slot] = '';
      if (slot === 'IMAGE URL1') update['Picture'] = '';
    }
  }
}

// If this product is already live on Shopify, flag the changed image slots so the
// separate Shopify Merge product sync Pipeline picks the row up and pushes the
// fresh URLs to the live product -- otherwise the sheet and Shopify silently
// drift apart (the sheet shows a working image, Shopify still has the dead one).
const alreadyOnShopify = String(iterJson['Shopify_Product_URL'] || '').trim() !== '' && String(iterJson['Shopify_Update_product_URL'] || '').trim() !== '';
if (alreadyOnShopify && updatedSlots.length > 0) {
  const existing = String(iterJson['Fields_to_update'] || '').split(',').map(f => f.trim()).filter(Boolean);
  const merged = Array.from(new Set([...existing, ...updatedSlots]));
  update['Fields_to_update'] = merged.join(',');
  update['Ready_to_post'] = 'yes';
}

return [{ json: update }];

// Every image goes through the resize node in one pass (branching here would
// split the per-product item stream and break the index-based aggregation
// downstream). The resized bytes are only *used* for images Shopify would
// reject; everything else is uploaded byte-for-byte as it came from Drive so
// normal photos are never re-encoded.
const resized  = $input.all();
const originals = $('⬇️ Download from Drive').all();
const meta      = $('🔀 Split Per Image').all();

return resized.map((item, i) => {
  const m = meta[i]?.json || {};
  const original = originals[i]?.binary?.data;
  const resizedBin = item.binary?.data;
  const resizable = /^image\/(jpeg|png)$/i.test(m.mimeType || '');
  const useResized = m.oversized && resizable && resizedBin && !item.json?.error;

  if (m.oversized && !useResized) {
    // Oversized but we could not safely resize it (unsupported format or the
    // resize itself failed) -- fail loudly instead of letting Shopify reject it
    // later with an opaque "Media processing failed".
    throw new Error(`Cannot downscale oversized image ${m.fileName} (${m.width}x${m.height}, ${m.mimeType}) for ${m.product_no}: ${item.json?.error || 'unsupported format'}`);
  }

  return {
    json: m,
    binary: { data: useResized ? resizedBin : original },
    pairedItem: { item: i }
  };
});

// Shopify processes uploads asynchronously; image.url is null until the file is
// READY. A fixed 15s wait was writing partial rows for slower images (the URL
// was silently skipped, leaving the slot empty forever). Now we keep polling
// until every file is READY, and fail loudly on FAILED.
const MAX_ATTEMPTS = 12; // ~3 minutes at 15s (covers processing + CDN propagation)
const res  = $json;
if (res?.errors?.length) {
  throw new Error('Shopify GraphQL error (get files): ' + JSON.stringify(res.errors));
}
const agg = $('📦 Aggregate Files').first().json;
let prev = 0;
try { prev = $('🧪 Check File Status').last()?.json?.attempts ?? 0; } catch (e) { prev = 0; } // first pass: no previous run yet
const attempts = prev + 1;

const nodes = res?.data?.nodes || [];
const byId = new Map(nodes.filter(Boolean).map(n => [n.id, n]));

const failed = [], pending = [];
for (const f of agg.uploadedFiles) {
  const n = byId.get(f.id);
  const status = n?.fileStatus;
  const url = n?.url || n?.image?.url;
  if (status === 'FAILED') failed.push(`${f.slot} (${f.fileName}) id=${f.id}`);
  else if (!url) pending.push(`${f.slot} (${f.fileName}) status=${status || 'missing'}`);
}
if (failed.length) {
  throw new Error(`Shopify rejected ${failed.length} image(s) for ${agg.product_no} (${agg.sheet_name} row ${agg.row_number}): ${failed.join(' | ')}`);
}
if (pending.length && attempts >= MAX_ATTEMPTS) {
  throw new Error(`Images still not READY after ${attempts} checks for ${agg.product_no} (${agg.sheet_name} row ${agg.row_number}): ${pending.join(' | ')}`);
}
return [{ json: { ...agg, attempts, pending: pending.length, nodes } }];

// Every file is READY -- but READY alone isn't proof the URL is live: Shopify can
// still rename a file during processing (name collision or CDN-unfriendly
// characters -> "_1"/uuid suffix = a different URL), and the CDN edge may lag.
// The sheet must only ever get a URL that has been confirmed live, otherwise
// we store a broken link that nothing downstream can recover from.
const { nodes = [], uploadedFiles = [] } = $json;
const idToUrl = {};
for (const n of nodes) { const url = n?.url || n?.image?.url; if (url) idToUrl[n.id] = url; }
return uploadedFiles.map(f => ({ json: { id: f.id, slot: f.slot, fileName: f.fileName, url: idToUrl[f.id] || '' } }));

const results = $input.all();
const checks  = $('🩺 Build Upload Verifications').all();
const status  = $('🧪 Check File Status').first().json; // nodes, uploadedFiles, row/sheet, attempts

const notLive = [];
for (let i = 0; i < results.length; i++) {
  const c = checks[i]?.json || {};
  const code = results[i]?.json?.statusCode;
  if (!c.url || code !== 200) notLive.push(`${c.slot} (${c.fileName}) ${c.url || 'no url'} -> ${code ?? results[i]?.json?.error ?? 'no response'}`);
}
if (notLive.length && status.attempts >= 12) {
  throw new Error(`Uploaded image URL(s) never became live for ${status.product_no} (${status.sheet_name} row ${status.row_number}): ${notLive.join(' | ')}`);
}
// Same shape Build Sheet Update expects; on retry the whole poll runs again so
// a renamed file's *new* URL is picked up rather than the stale one.
return [{ json: { ...status, unavailable: notLive.length, notLive } }];
